        for a in range(i):
            if lst[a][1]<lst[a+1][1]:
                temp = lst[a]
                lst[a] = lst[a+1]
                lst[a+1] = temp
    return lst

def sort_age(lst):
    lst.sort(key=lambda x: x[((1) - 1) - 1], reverse=True)
    return lst

def sort_age(lst):
    new = []
    for x in lst:
        index = 0
        for i in new:
            if x[1] < i[1]:
                index += 1
        new.insert(index,x)
    return new
